          reply_to_review:
            '- key: reply_to_review\n  tool: add_reply_to_pull_request_comment\n  connection: github_source # bind:source\n  with:\n    owner: ${{ jobs.implement.outputs.owner }}\n    repo: ${{ jobs.implement.outputs.repo }}\n    pull_number: ${{ jobs.implement.outputs.pr_number }}\n    comment_id: ${{ execution.events[0].data.comment.id }}\n    body: ${{ steps.review.outputs.reply }}\n',
